SELECT SCHEME_ID AS "schemeId", SCHEME_CODE AS "schemeCode", SCHEME_NAME AS "schemeName", SCHEME_TYPE AS "schemeType", SCHEME_TYPE AS "estimationType", ESTIMATION_METHOD AS "estimationMethod", APPLICABLE_SCOPE AS "applicableScope", SCHEME_DESCRIPTION AS "schemeDescription", SCHEME_DESCRIPTION AS "description", IS_ENABLED AS "isEnabled", VERSION AS "version", EFFECTIVE_DATE AS "effectiveDate", EXPIRY_DATE AS "expiryDate", CREATE_TIME AS "createTime" FROM TBL_COST_ESTIMATION_SCHEME WHERE 1 = 1
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND SCHEME_CODE LIKE '%' || #{schemeCode} || '%'
AND SCHEME_NAME LIKE '%' || #{schemeName} || '%'
AND SCHEME_TYPE = #{schemeType}
AND IS_ENABLED = #{isEnabled}
ORDER BY CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_COST_ESTIMATION_SCHEME
WHERE 1 = 1

      AND BOOK_ID = #{bookId}


      AND TENANT_ID = #{tenantId}


      AND SCHEME_CODE LIKE '%' || #{schemeCode} || '%'


      AND SCHEME_NAME LIKE '%' || #{schemeName} || '%'


      AND SCHEME_TYPE = #{schemeType}


      AND IS_ENABLED = #{isEnabled}

SELECT COUNT(1)
FROM TBL_COST_ESTIMATION_SCHEME
WHERE SCHEME_CODE = #{schemeCode}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

      AND SCHEME_ID != #{schemeId}
